/**
 * @event
 * @name scwin.grd_resultList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_resultList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.loadForm === 'function') { scwin.loadForm(r["isuexerDd"], r["isuexerRnd"], r["disclsDd"], r["isuTpCd"], r["exerPayTpCd"], r["ncovexerUsdAmt"], r["exchrt"], r["ncovexerAmt"], r["convexerPrc"], r["convexerUsdAmt"], r["convexerAmt"], r["convShrs"], r["clmStrtDd"], r["clmEndDd"], r["expDd"], r["remk"]); } else { console.error('[sdd] 행 동작 미정의: scwin.loadForm (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.loadForm'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};


