/**
 * @method
 * @name scwin.loadForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param isuexerDd isuexerRnd disclsDd isuTpCd exerPayTpCd ncovexerUsdAmt exchrt ncovexerAmt convexerPrc convexerUsdAmt convexerAmt convShrs clmStrtDd clmEndDd expDd remk
 * @returns
 * @hidden N
*/
scwin.loadForm = function (isuexerDd, isuexerRnd, disclsDd, isuTpCd, exerPayTpCd, ncovexerUsdAmt, exchrt, ncovexerAmt, convexerPrc, convexerUsdAmt, convexerAmt, convShrs, clmStrtDd, clmEndDd, expDd, remk) {
    /* sdd-asis-lifecycle:begin fn_LoadForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_isuexerDdCheck").setValue($c.date.dateUnFormat(isuexerDd));
    $c.util.getComponent("ipt_isuexerRndCheck").setValue(isuexerRnd);
    $c.util.getComponent('ipt_isuexerDd').setValue($c.date.dateUnFormat(isuexerDd));
    $c.util.getComponent('ipt_isuexerRnd').setValue(isuexerRnd);
    $c.util.getComponent('ipt_disclsDd').setValue($c.date.dateUnFormat(disclsDd));
    (($c.util.getComponent('slc_isuTpCd'))?.setValue?.(isuTpCd));
    (($c.util.getComponent('slc_exerPayTpCd'))?.setValue?.(exerPayTpCd));
    $c.util.getComponent('ipt_ncovexerUsdAmt').setValue($c.num.formatNumber(ncovexerUsdAmt));
    $c.util.getComponent('ipt_exchrt').setValue($c.num.formatNumber(exchrt));
    $c.util.getComponent('ipt_ncovexerAmt').setValue($c.num.formatNumber(ncovexerAmt));
    $c.util.getComponent('ipt_convexerPrc').setValue($c.num.formatNumber(convexerPrc));
    $c.util.getComponent('ipt_convexerUsdAmt').setValue($c.num.formatNumber(convexerUsdAmt));
    $c.util.getComponent('ipt_convexerAmt').setValue($c.num.formatNumber(convexerAmt));
    $c.util.getComponent('ipt_convShrs').setValue($c.num.formatNumber(convShrs));
    $c.util.getComponent('ipt_clmStrtDd').setValue($c.date.dateUnFormat(clmStrtDd));
    $c.util.getComponent('ipt_clmEndDd').setValue($c.date.dateUnFormat(clmEndDd));
    $c.util.getComponent('ipt_expDd').setValue($c.date.dateUnFormat(expDd));
    $c.util.getComponent('ipt_remk').setValue(remk);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.calAmt
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.calAmt = function () {
    /* sdd-asis-lifecycle:begin fn_CalAmt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_ncovexerAmt').setValue($c.num.formatNumber((scwin.rmComma($c.util.getComponent('ipt_ncovexerUsdAmt').getValue()) * scwin.rmComma($c.util.getComponent('ipt_exchrt').getValue()))));
    /* sdd-asis-lifecycle:end */
};


