/**
 * @method
 * @name scwin.rmComma
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.rmComma = function (str) {
    /* sdd-asis-lifecycle:begin fn_RmComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    //	if( str == null || str == "" || str == 0 ) return '';
    //	if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);			//2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");  

    return Number(str.replace(reg,''));
    /* sdd-asis-lifecycle:end */
};
